from drf_spectacular.utils import (
    extend_schema, extend_schema_view, OpenApiExample, OpenApiResponse,
)
from drf_spectacular.openapi import OpenApiTypes


@extend_schema_view(
    list=extend_schema(
        summary="لیست مقالات",
        description="مقالات منتشرشده با فیلتر دسته.",
        examples=[
            OpenApiExample("نمونه", value={"id": 1, "title": "..."}, response_only=True),
        ],
    ),
    retrieve=extend_schema(summary="جزئیات مقاله"),
    create=extend_schema(
        summary="ساخت مقاله",
        responses={201: None, 400: OpenApiResponse(description="داده نامعتبر")},
    ),
)
class ArticleViewSet(viewsets.ModelViewSet):
    queryset = Article.objects.all()
    serializer_class = ArticleSerializer

    @extend_schema(
        summary="انتشار مقاله",
        request=None,
        responses={
            200: OpenApiResponse(description="منتشر شد"),
            400: OpenApiResponse(description="قبلاً منتشر شده"),
        },
        examples=[
            OpenApiExample("پاسخ موفق", value={"status": "published"}, response_only=True),
        ],
    )
    @action(detail=True, methods=["post"])
    def publish(self, request, pk=None):
        article = self.get_object()
        if article.is_published:
            return Response({"detail": "قبلاً منتشر شده"}, status=400)
        article.is_published = True
        article.save(update_fields=["is_published"])
        return Response({"status": "published"})
